// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle, and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const SUBSTEPS = 4;
  const sdt = dt / SUBSTEPS;

  for (let i = 0; i < SUBSTEPS; i++) {
    ball.x += ball.vx * sdt;
    ball.y += ball.vy * sdt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    // Bricks
    let bouncedX = false;
    let bouncedY = false;
    for (const brick of state.bricks) {
      if (!brick.alive) continue;

      if (collides(ball, brick)) {
        // Calculate penetration on each axis
        const ox = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
        const oy = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

        if (ox < oy) {
          // Side hit
          if (!bouncedX) {
            ball.vx = -ball.vx;
            bouncedX = true;
          }
          // Push out
          ball.x = ball.vx < 0 ? brick.x + brick.w + ball.r : brick.x - ball.r;
        } else if (oy < ox) {
          // Top/Bottom hit
          if (!bouncedY) {
            ball.vy = -ball.vy;
            bouncedY = true;
          }
          // Push out
          ball.y = ball.vy < 0 ? brick.y + brick.h + ball.r : brick.y - ball.r;
        } else {
          // Corner hit (ox === oy)
          if (!bouncedX) { ball.vx = -ball.vx; bouncedX = true; }
          if (!bouncedY) { ball.vy = -ball.vy; bouncedY = true; }
          // Push out both
          ball.x = ball.vx < 0 ? brick.x + brick.w + ball.r : brick.x - ball.r;
          ball.y = ball.vy < 0 ? brick.y + brick.h + ball.r : brick.y - ball.r;
        }

        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
    }

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

